import csv

# Read patient sex data
male_patients = set()
with open('patient_sex.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['SEX'] == 'M':
            male_patients.add(row['ID'])

print(f"Number of male patients: {len(male_patients)}")
print(f"Male patient IDs: {sorted(male_patients)[:10]}...")

# Check some sample WBC values for male patients
wbc_values = []
fg_values = []

with open('csv/Laboratory.csv', 'r') as f:
    reader = csv.DictReader(f)
    count = 0
    for row in reader:
        pid = row['ID']
        if pid not in male_patients:
            continue

        wbc_str = row.get('WBC', '').strip()
        fg_str = row.get('FG', '').strip()

        if wbc_str:
            try:
                wbc = float(wbc_str)
                wbc_values.append((pid, wbc))
            except ValueError:
                pass

        if fg_str:
            try:
                fg = float(fg_str)
                fg_values.append((pid, fg))
            except ValueError:
                pass

        count += 1
        if count > 100:
            break

print(f"\nSample WBC values for male patients (first 20):")
for pid, wbc in wbc_values[:20]:
    print(f"  ID={pid}, WBC={wbc}")

print(f"\nSample FG values for male patients (first 20):")
for pid, fg in fg_values[:20]:
    print(f"  ID={pid}, FG={fg}")

